with d as (select value r from jsonb_array_elements($q$[{"slug":"moqueca","title":"Moqueca","cuisine":"latin-american","meal_types":["dinner"],"diets":["pescatarian","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":60,"recipe":{"id":"moqueca","title":"Moqueca","summary":"A Brazilian fish and prawn stew, simmered gently in coconut milk with capsicum, tomato and lime.","cuisine":"latin-american","diets":["pescatarian","no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":30,"cookMinutes":30,"servings":4,"onePot":true,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Seafood","items":[{"item":"firm white fish fillets","raw":"600g firm white fish fillets, skinless, cut into 5cm pieces","quantity":600,"unit":"g","ingredientId":"white-fish","prep":"skinless, cut into 5cm pieces"},{"item":"raw prawns","raw":"300g raw prawns, peeled and deveined","quantity":300,"unit":"g","ingredientId":"prawn","prep":"peeled and deveined"},{"item":"limes","raw":"Juice of 2 limes","quantity":2,"ingredientId":"lime","prep":"juiced"},{"item":"garlic","raw":"2 garlic cloves, crushed","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"}]},{"title":"Stew","items":[{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"brown onion","raw":"1 brown onion, sliced into thin rings","quantity":1,"ingredientId":"brown-onion","prep":"sliced into thin rings"},{"item":"red capsicum","raw":"1 red capsicum, sliced","quantity":1,"ingredientId":"capsicum","prep":"sliced"},{"item":"yellow capsicum","raw":"1 yellow capsicum, sliced","quantity":1,"ingredientId":"capsicum","prep":"sliced"},{"item":"tomatoes","raw":"3 tomatoes, sliced","quantity":3,"ingredientId":"tomato","prep":"sliced"},{"item":"sweet paprika","raw":"1 tsp sweet paprika","quantity":1,"unit":"tsp","ingredientId":"paprika"},{"item":"red chilli","raw":"1 red chilli, finely chopped","quantity":1,"ingredientId":"red-chilli","prep":"finely chopped"},{"item":"coconut milk","raw":"400ml coconut milk","quantity":400,"unit":"ml","ingredientId":"coconut-milk"},{"item":"coriander","raw":"Handful of coriander, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"}]},{"title":"To serve","items":[{"item":"Steamed white rice","raw":"Steamed white rice, to serve","ingredientId":"white-rice","prep":"to serve"},{"item":"lime","raw":"1 lime, cut into wedges","quantity":1,"ingredientId":"lime","prep":"cut into wedges"}]}],"steps":[{"text":"Toss the fish and prawns with the lime juice, garlic and salt. Cover and refrigerate for 15 to 20 minutes, no longer, or the lime starts to firm the fish."},{"text":"Heat the oil in a wide, deep frying pan or casserole over medium heat. Cook the onion for 5 minutes until soft, then add the capsicums and cook for 5 minutes more. Stir in the paprika and chilli."},{"text":"Lay the tomato slices over the vegetables, pour in the coconut milk and bring to a gentle simmer for 5 minutes."},{"text":"Nestle the fish into the sauce with its marinade, cover and simmer gently for 6 minutes. Add the prawns and cook for 3 to 4 minutes more, until the prawns are pink and the fish is opaque and flakes easily."},{"text":"Taste for salt, scatter with coriander and serve with rice and lime wedges."}],"notes":["In Bahia it's finished with a spoonful of red palm oil (dendê), sold at African and Latin grocers.","Keep the simmer gentle once the fish goes in, so the pieces stay whole.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part. Cook prawns and other crustaceans until the shells turn pink and the flesh is opaque and firm."],"source":"user","provenance":"ai-draft"}},{"slug":"eggs-benedict","title":"Eggs Benedict","cuisine":"american","meal_types":["breakfast"],"diets":[],"difficulty":"medium","total_minutes":30,"recipe":{"id":"eggs-benedict","title":"Eggs Benedict","summary":"Poached eggs and ham on toasted English muffins, under a lemony, buttery hollandaise.","cuisine":"american","diets":[],"mealTypes":["breakfast"],"difficulty":"medium","prepMinutes":10,"cookMinutes":20,"servings":2,"onePot":false,"ingredientGroups":[{"title":"Hollandaise","items":[{"item":"egg yolks","raw":"2 egg yolks","quantity":2,"ingredientId":"egg"},{"item":"lemon juice","raw":"1 tbsp lemon juice","quantity":1,"unit":"tbsp","ingredientId":"lemon"},{"item":"butter","raw":"125g butter, melted and kept warm","quantity":125,"unit":"g","ingredientId":"butter","prep":"melted and kept warm"},{"item":"salt","raw":"1/4 tsp salt","quantity":0.25,"unit":"tsp","ingredientId":"salt"},{"item":"cayenne pepper","raw":"Pinch of cayenne pepper","quantity":1,"unit":"pinch","ingredientId":"cayenne"}]},{"title":"Eggs","items":[{"item":"eggs","raw":"4 eggs, very fresh","quantity":4,"ingredientId":"egg","prep":"very fresh"},{"item":"white vinegar","raw":"1 tbsp white vinegar","quantity":1,"unit":"tbsp","ingredientId":"white-vinegar"},{"item":"English muffins","raw":"2 English muffins, split","quantity":2,"ingredientId":"english-muffin","prep":"split"},{"item":"butter","raw":"10g butter, softened","quantity":10,"unit":"g","ingredientId":"butter","prep":"softened"},{"item":"leg ham","raw":"4 slices leg ham","quantity":4,"unit":"slice","ingredientId":"ham"},{"item":"chives","raw":"1 tbsp chives, finely chopped","quantity":1,"unit":"tbsp","ingredientId":"chives","prep":"finely chopped"}]}],"steps":[{"text":"For the hollandaise, bring a small saucepan of water to a bare simmer. In a heatproof bowl that sits snugly over the pan without touching the water, whisk the egg yolks, lemon juice and 1 tbsp water for 2 to 3 minutes, until pale, thick and leaving a trail."},{"text":"Take the bowl off the heat and whisk in the warm butter a few drops at a time, then in a thin stream, until thick and glossy. Season with the salt and cayenne. If it gets too thick, whisk in a teaspoon of warm water. Keep it warm over the pan, off the heat."},{"text":"Bring a wide saucepan of water to a gentle simmer and add the vinegar. Crack each egg into a cup. Stir the water into a slow whirlpool, slip in two eggs and poach for 3 minutes, until the whites are set. Lift out onto paper towel and repeat."},{"text":"Meanwhile, toast the muffins until golden and crisp at the edges, and butter them. Warm the ham briefly in a dry frying pan until it is hot and just starting to sizzle."},{"text":"Top each muffin half with ham and a poached egg, spoon over the hollandaise and scatter with chives. Serve straight away."}],"notes":["Soft-yolked eggs and hollandaise made with lightly cooked yolks aren't recommended for pregnant people, young children, older people or anyone with a weakened immune system. For them, poach the eggs for 5 minutes until the yolks are firm and leave off the hollandaise.","If the hollandaise splits, whisk a fresh yolk in a clean bowl over the water and slowly whisk the split sauce into it.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"french-toast","title":"French Toast","cuisine":"american","meal_types":["breakfast"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"french-toast","title":"French Toast","summary":"Thick slices of day-old bread soaked in cinnamon custard and fried in butter until golden.","cuisine":"american","diets":["vegetarian"],"mealTypes":["breakfast"],"difficulty":"easy","prepMinutes":10,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"title":"French toast","items":[{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"milk","raw":"250ml milk","quantity":250,"unit":"ml","ingredientId":"milk"},{"item":"caster sugar","raw":"2 tbsp caster sugar","quantity":2,"unit":"tbsp","ingredientId":"caster-sugar"},{"item":"vanilla extract","raw":"1 tsp vanilla extract","quantity":1,"unit":"tsp","ingredientId":"vanilla-extract"},{"item":"ground cinnamon","raw":"1/2 tsp ground cinnamon","quantity":0.5,"unit":"tsp","ingredientId":"ground-cinnamon"},{"item":"salt","raw":"Pinch of salt","quantity":1,"unit":"pinch","ingredientId":"salt"},{"item":"day-old white bread","raw":"8 slices day-old white bread, about 2cm thick","quantity":8,"unit":"slice","ingredientId":"white-bread","prep":"about 2cm thick"},{"item":"butter","raw":"40g butter","quantity":40,"unit":"g","ingredientId":"butter"}]},{"title":"To serve","items":[{"item":"Maple syrup","raw":"Maple syrup","ingredientId":"maple-syrup"},{"item":"frozen mixed berries","raw":"150g frozen mixed berries, thawed","quantity":150,"unit":"g","ingredientId":"frozen-berries","prep":"thawed"},{"item":"Icing sugar","raw":"Icing sugar, for dusting","ingredientId":"icing-sugar","prep":"for dusting"}]}],"steps":[{"text":"Heat the oven to 120°C (100°C fan-forced) to keep the first batch warm."},{"text":"Whisk the eggs, milk, sugar, vanilla, cinnamon and salt in a wide, shallow dish."},{"text":"Melt a quarter of the butter in a large frying pan over medium-low heat. Soak two slices of bread in the custard for 20 to 30 seconds a side, until soaked through but not falling apart."},{"text":"Fry for 3 minutes a side, until deep golden and the middle feels set when pressed. Keep warm in the oven while you cook the rest, adding butter to the pan each time."},{"text":"Serve with maple syrup and berries, dusted with icing sugar."}],"notes":["Day-old bread soaks up the custard without going soggy. Fresh bread works if you dry the slices in a low oven for 10 minutes first.","Thick slices of brioche make a richer version."],"source":"user","provenance":"ai-draft"}},{"slug":"blackened-fish","title":"Blackened Fish","cuisine":"american","meal_types":["dinner"],"diets":["pescatarian","no-gluten"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"blackened-fish","title":"Blackened Fish","summary":"White fish crusted in a smoky Cajun spice mix and seared hard in butter, with a crunchy slaw.","cuisine":"american","diets":["pescatarian","no-gluten"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":15,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Spice mix","items":[{"item":"sweet paprika","raw":"2 tsp sweet paprika","quantity":2,"unit":"tsp","ingredientId":"paprika"},{"item":"smoked paprika","raw":"1 tsp smoked paprika","quantity":1,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"garlic powder","raw":"1 tsp garlic powder","quantity":1,"unit":"tsp","ingredientId":"garlic-powder"},{"item":"onion powder","raw":"1 tsp onion powder","quantity":1,"unit":"tsp","ingredientId":"onion-powder"},{"item":"dried thyme","raw":"1 tsp dried thyme","quantity":1,"unit":"tsp","ingredientId":"dried-thyme"},{"item":"dried oregano","raw":"1 tsp dried oregano","quantity":1,"unit":"tsp","ingredientId":"dried-oregano"},{"item":"cayenne pepper","raw":"1/2 tsp cayenne pepper","quantity":0.5,"unit":"tsp","ingredientId":"cayenne"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"Fish","items":[{"item":"firm white fish","raw":"4 firm white fish fillets, skinless, about 180g each","quantity":4,"unit":"fillet","ingredientId":"white-fish","prep":"skinless, about 180g each"},{"item":"butter","raw":"40g butter, melted","quantity":40,"unit":"g","ingredientId":"butter","prep":"melted"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"lemon","raw":"1 lemon, cut into wedges","quantity":1,"ingredientId":"lemon","prep":"cut into wedges"}]},{"title":"Slaw","items":[{"item":"red cabbage","raw":"200g red cabbage, finely shredded","quantity":200,"unit":"g","ingredientId":"red-cabbage","prep":"finely shredded"},{"item":"carrot","raw":"1 carrot, grated","quantity":1,"ingredientId":"carrot","prep":"grated"},{"item":"spring onions","raw":"2 spring onions, thinly sliced","quantity":2,"ingredientId":"spring-onion","prep":"thinly sliced"},{"item":"mayonnaise","raw":"3 tbsp mayonnaise","quantity":3,"unit":"tbsp","ingredientId":"mayonnaise"},{"item":"apple cider vinegar","raw":"1 tbsp apple cider vinegar","quantity":1,"unit":"tbsp","ingredientId":"apple-cider-vinegar"},{"item":"salt","raw":"Pinch of salt","quantity":1,"unit":"pinch","ingredientId":"salt"}]},{"title":"To serve","items":[{"item":"Steamed white rice","raw":"Steamed white rice, to serve","ingredientId":"white-rice","prep":"to serve"}]}],"steps":[{"text":"Mix the slaw ingredients in a bowl and set aside."},{"text":"Mix the spices, salt and pepper on a plate. Pat the fish dry, brush both sides with half the melted butter and press into the spice mix to coat."},{"text":"Open a window and turn on the range hood: this gets smoky. Heat a heavy frying pan (cast iron is best) over high heat for 3 minutes, then add the oil."},{"text":"Cook the fish for 2 to 3 minutes a side, depending on thickness, until the crust is very dark and the fish is opaque and flakes easily. Drizzle the rest of the butter over in the last minute."},{"text":"Serve with the slaw, rice and lemon wedges."}],"notes":["Use firm fillets about 2cm thick, such as ling, barramundi or snapper. Thin fillets overcook before the crust forms.","Some ready-made Cajun seasonings are very salty. If you use one instead of the mix here, leave out the salt.","Food safety: Use very fresh seafood from a trusted supplier for anything served raw or lightly cured, keep it refrigerated and serve it promptly; pregnant women, older people and young children should avoid raw seafood."],"source":"user","provenance":"ai-draft"}},{"slug":"pot-roast","title":"Pot Roast","cuisine":"american","meal_types":["dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":220,"recipe":{"id":"pot-roast","title":"Pot Roast","summary":"Beef chuck braised slowly in red wine and stock with carrots and potatoes until it falls apart.","cuisine":"american","diets":["no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":20,"cookMinutes":200,"servings":6,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"beef chuck roast","raw":"1.5kg beef chuck roast, in one piece","quantity":1.5,"unit":"kg","ingredientId":"beef-chuck","prep":"in one piece"},{"item":"salt","raw":"2 tsp salt","quantity":2,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1 tsp black pepper","quantity":1,"unit":"tsp","ingredientId":"black-pepper"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onions","raw":"2 brown onions, cut into wedges","quantity":2,"ingredientId":"brown-onion","prep":"cut into wedges"},{"item":"garlic","raw":"4 garlic cloves, crushed","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"tomato paste","raw":"2 tbsp tomato paste","quantity":2,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"plain flour","raw":"2 tbsp plain flour","quantity":2,"unit":"tbsp","ingredientId":"plain-flour"},{"item":"red wine","raw":"250ml red wine (or more beef stock)","quantity":250,"unit":"ml","ingredientId":"red-wine","note":"or more beef stock"},{"item":"beef stock","raw":"500ml beef stock","quantity":500,"unit":"ml","ingredientId":"beef-stock"},{"item":"Worcestershire sauce","raw":"1 tbsp Worcestershire sauce","quantity":1,"unit":"tbsp","ingredientId":"worcestershire-sauce"},{"item":"thyme","raw":"3 thyme sprigs","quantity":3,"unit":"sprig","ingredientId":"thyme"},{"item":"bay","raw":"2 bay leaves","quantity":2,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"carrots","raw":"4 carrots, cut into 5cm pieces","quantity":4,"ingredientId":"carrot","prep":"cut into 5cm pieces"},{"item":"celery","raw":"2 celery sticks, cut into 5cm pieces","quantity":2,"unit":"stick","ingredientId":"celery","prep":"cut into 5cm pieces"},{"item":"baby potatoes","raw":"800g baby potatoes, halved","quantity":800,"unit":"g","ingredientId":"waxy-potato","prep":"halved"},{"item":"parsley","raw":"Handful of parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped"}]}],"steps":[{"text":"Heat the oven to 160°C (140°C fan-forced). Pat the beef dry and season all over with the salt and pepper."},{"text":"Heat the oil in a large flameproof casserole with a lid over medium-high heat. Brown the beef well on all sides, about 10 minutes. Set aside."},{"text":"Turn the heat to medium. Cook the onions for 5 minutes, then stir in the garlic and tomato paste for 1 minute and the flour for 1 minute more."},{"text":"Pour in the wine and bubble for 2 minutes, scraping up the browned bits. Add the stock, Worcestershire, thyme and bay leaves. Return the beef, bring to a simmer, cover and cook in the oven for 1 1/2 hours."},{"text":"Turn the beef, then add the carrots, celery and potatoes around it, pushing them into the liquid. Cover and cook for 1 1/2 hours more, until the beef is very tender and the vegetables are soft."},{"text":"Rest the beef for 10 minutes, then pull it into thick pieces. Skim any fat from the gravy and taste for salt. Serve the beef and vegetables with plenty of gravy, scattered with parsley."}],"notes":["Chuck has the connective tissue that melts into tenderness over a long braise. Leaner cuts like topside go dry.","Leftovers make great sandwiches the next day.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"welsh-rarebit","title":"Welsh Rarebit","cuisine":"british","meal_types":["lunch","snack"],"diets":["pescatarian"],"difficulty":"easy","total_minutes":25,"recipe":{"id":"welsh-rarebit","title":"Welsh Rarebit","summary":"A savoury cheddar, ale and mustard sauce spread thickly on toast and grilled until bubbling.","cuisine":"british","diets":["pescatarian"],"mealTypes":["lunch","snack"],"difficulty":"easy","prepMinutes":10,"cookMinutes":15,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Rarebit","items":[{"item":"butter","raw":"25g butter","quantity":25,"unit":"g","ingredientId":"butter"},{"item":"plain flour","raw":"25g plain flour","quantity":25,"unit":"g","ingredientId":"plain-flour"},{"item":"beer","raw":"150ml beer (brown ale or stout)","quantity":150,"unit":"ml","ingredientId":"beer","note":"brown ale or stout"},{"item":"English mustard","raw":"1 tsp English mustard","quantity":1,"unit":"tsp","ingredientId":"english-mustard"},{"item":"Worcestershire sauce","raw":"1 tbsp Worcestershire sauce","quantity":1,"unit":"tbsp","ingredientId":"worcestershire-sauce"},{"item":"mature cheddar","raw":"200g mature cheddar, grated","quantity":200,"unit":"g","ingredientId":"cheddar","prep":"grated"},{"item":"egg yolk","raw":"1 egg yolk","quantity":1,"ingredientId":"egg"},{"item":"black pepper","raw":"Pinch of black pepper","quantity":1,"unit":"pinch","ingredientId":"black-pepper"}]},{"title":"To serve","items":[{"item":"sourdough","raw":"4 slices sourdough, thickly cut","quantity":4,"unit":"slice","ingredientId":"sourdough","prep":"thickly cut"},{"item":"Salad leaves","raw":"Salad leaves, to serve","ingredientId":"salad-leaves","prep":"to serve"}]}],"steps":[{"text":"Melt the butter in a small saucepan over medium heat. Stir in the flour and cook for 1 minute."},{"text":"Gradually whisk in the beer until smooth, then the mustard and Worcestershire. Simmer for 2 minutes until thick."},{"text":"Take the pan off the heat and stir in the cheese until melted, then the egg yolk and pepper. Leave to cool for 5 minutes, until it's a thick paste."},{"text":"Heat the grill to high. Toast the bread on both sides under the grill until golden and crisp."},{"text":"Spread the cheese mixture thickly over the toast, right to the edges. Grill for 3 to 4 minutes, until bubbling and browned in patches. Serve hot with salad leaves."}],"notes":["Worcestershire sauce contains anchovies, so this isn't vegetarian. Some brands make an anchovy-free version.","The cheese mixture keeps for 3 days in the fridge, ready for quick lunches."],"source":"user","provenance":"ai-draft"}},{"slug":"cornish-pasties","title":"Cornish Pasties","cuisine":"british","meal_types":["lunch"],"diets":[],"difficulty":"medium","total_minutes":110,"recipe":{"id":"cornish-pasties","title":"Cornish Pasties","summary":"Short pastry crimped around raw beef, potato, swede and onion, baked so the filling steams in its own juices.","cuisine":"british","diets":[],"mealTypes":["lunch"],"difficulty":"medium","prepMinutes":60,"cookMinutes":50,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Pastry","items":[{"item":"plain flour","raw":"500g plain flour","quantity":500,"unit":"g","ingredientId":"plain-flour"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"cold butter","raw":"250g cold butter, diced","quantity":250,"unit":"g","ingredientId":"butter","prep":"diced"},{"item":"iced water","raw":"160ml iced water","quantity":160,"unit":"ml","ingredientId":"water"}]},{"title":"Filling","items":[{"item":"beef skirt steak","raw":"450g beef skirt steak, cut into 1cm pieces","quantity":450,"unit":"g","ingredientId":"skirt-steak","prep":"cut into 1cm pieces"},{"item":"potatoes","raw":"350g potatoes, peeled and thinly sliced","quantity":350,"unit":"g","ingredientId":"potato","prep":"peeled and thinly sliced"},{"item":"swede","raw":"200g swede, peeled and thinly sliced","quantity":200,"unit":"g","ingredientId":"swede","prep":"peeled and thinly sliced"},{"item":"brown onion","raw":"1 brown onion, finely chopped","quantity":1,"ingredientId":"brown-onion","prep":"finely chopped"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1 tsp black pepper","quantity":1,"unit":"tsp","ingredientId":"black-pepper"},{"item":"butter","raw":"20g butter, cut into 4","quantity":20,"unit":"g","ingredientId":"butter","prep":"cut into 4"},{"item":"egg","raw":"1 egg, beaten, for brushing","quantity":1,"ingredientId":"egg","prep":"beaten, for brushing"}]}],"steps":[{"text":"For the pastry, mix the flour and salt in a bowl and rub in the butter with your fingertips until it looks like coarse breadcrumbs. Add the water and bring together into a dough without kneading much. Wrap and chill for 30 minutes."},{"text":"Heat the oven to 200°C (180°C fan-forced) and line a large tray with baking paper."},{"text":"Cut the pastry into four pieces and roll each out on a floured bench to a circle about 22cm across and 4mm thick, using a plate as a guide."},{"text":"Layer a quarter of the potato, swede, onion and beef across the middle of each circle, seasoning each layer with salt and plenty of pepper. Top with a piece of butter."},{"text":"Brush the edge with egg, bring the pastry up over the filling and press the edges together along the top until sealed. Crimp the seam by folding it over itself in small pleats. Cut a small steam hole in each side and brush all over with egg until evenly glossy, so the pastry bakes until golden."},{"text":"Bake for 20 minutes, then turn the oven down to 170°C (150°C fan-forced) and bake for 30 minutes more, until deep golden and a skewer slides easily through the vegetables. Rest for 10 minutes before eating."}],"notes":["Everything goes in raw: the beef and vegetables cook in the steam sealed inside the pastry, so cut them small and thin.","Skirt is the traditional cut. Chuck steak works too, cut finely.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"fish-pie","title":"Fish Pie","cuisine":"british","meal_types":["dinner"],"diets":["pescatarian"],"difficulty":"medium","total_minutes":100,"recipe":{"id":"fish-pie","title":"Fish Pie","summary":"White fish, salmon, smoked salmon and prawns in a creamy parsley sauce under a buttery mash crust.","cuisine":"british","diets":["pescatarian"],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":30,"cookMinutes":70,"servings":6,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Mash","items":[{"item":"floury potatoes","raw":"1.2kg floury potatoes, peeled and quartered","quantity":1.2,"unit":"kg","ingredientId":"potato","prep":"peeled and quartered"},{"item":"butter","raw":"50g butter","quantity":50,"unit":"g","ingredientId":"butter"},{"item":"milk","raw":"100ml milk","quantity":100,"unit":"ml","ingredientId":"milk"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"cheddar","raw":"30g cheddar, grated","quantity":30,"unit":"g","ingredientId":"cheddar","prep":"grated"}]},{"title":"Filling","items":[{"item":"milk","raw":"600ml milk","quantity":600,"unit":"ml","ingredientId":"milk"},{"item":"bay","raw":"1 bay leaf","quantity":1,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"brown onion","raw":"1/2 brown onion","quantity":0.5,"ingredientId":"brown-onion"},{"item":"butter","raw":"50g butter","quantity":50,"unit":"g","ingredientId":"butter"},{"item":"plain flour","raw":"50g plain flour","quantity":50,"unit":"g","ingredientId":"plain-flour"},{"item":"Dijon mustard","raw":"1 tsp Dijon mustard","quantity":1,"unit":"tsp","ingredientId":"dijon-mustard"},{"item":"lemon juice","raw":"1 tbsp lemon juice","quantity":1,"unit":"tbsp","ingredientId":"lemon"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"firm white fish fillets","raw":"400g firm white fish fillets, skinless, cut into 3cm pieces","quantity":400,"unit":"g","ingredientId":"white-fish","prep":"skinless, cut into 3cm pieces"},{"item":"salmon fillet","raw":"250g salmon fillet, skinless, cut into 3cm pieces","quantity":250,"unit":"g","ingredientId":"salmon","prep":"skinless, cut into 3cm pieces"},{"item":"hot-smoked salmon","raw":"150g hot-smoked salmon, flaked","quantity":150,"unit":"g","ingredientId":"smoked-salmon","prep":"flaked"},{"item":"raw prawns","raw":"200g raw prawns, peeled and deveined","quantity":200,"unit":"g","ingredientId":"prawn","prep":"peeled and deveined"},{"item":"frozen peas","raw":"100g frozen peas","quantity":100,"unit":"g","ingredientId":"frozen-peas"},{"item":"parsley","raw":"3 tbsp parsley, chopped","quantity":3,"unit":"tbsp","ingredientId":"parsley","prep":"chopped"}]}],"steps":[{"text":"Boil the potatoes in salted water for 18 to 20 minutes until tender. Drain well, mash with the butter, milk and salt, and set aside."},{"text":"Meanwhile, warm the milk with the bay leaf and onion in a saucepan until steaming. Turn off the heat and leave for 10 minutes, then discard the bay leaf and onion."},{"text":"Heat the oven to 200°C (180°C fan-forced). Melt the butter in a clean saucepan over medium heat, stir in the flour and cook for 1 minute. Gradually whisk in the warm milk and simmer for 3 minutes, stirring, until thick. Stir in the mustard, lemon juice and salt, and take off the heat."},{"text":"Spread the raw fish, salmon, smoked salmon, prawns and peas in a 2.5L baking dish. Stir the parsley through the sauce and pour it over evenly."},{"text":"Spoon the mash over the top, starting at the edges to seal in the filling, rough it up with a fork and scatter with the cheese."},{"text":"Bake for 30 to 35 minutes, until the top is golden and the filling is bubbling at the edges. Check a piece of fish in the middle: it should be opaque and flake easily. Rest for 5 minutes before serving."}],"notes":["Fish pie packs from the supermarket seafood counter make this quicker; use 1kg in total.","Assemble up to a day ahead and keep covered in the fridge. Bake from cold for 45 minutes.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part. Cook prawns and other crustaceans until the shells turn pink and the flesh is opaque and firm."],"source":"user","provenance":"ai-draft"}},{"slug":"scotch-eggs","title":"Scotch Eggs","cuisine":"british","meal_types":["snack","lunch"],"diets":["no-dairy"],"difficulty":"medium","total_minutes":70,"recipe":{"id":"scotch-eggs","title":"Scotch Eggs","summary":"Jammy-yolked eggs wrapped in herby sausage meat, crumbed and fried until crisp.","cuisine":"british","diets":["no-dairy"],"mealTypes":["snack","lunch"],"difficulty":"medium","prepMinutes":40,"cookMinutes":30,"servings":6,"onePot":false,"ingredientGroups":[{"title":"Eggs","items":[{"item":"eggs","raw":"6 eggs, at room temperature","quantity":6,"ingredientId":"egg","prep":"at room temperature"},{"item":"pork sausage mince","raw":"500g pork sausage mince","quantity":500,"unit":"g","ingredientId":"pork-sausage"},{"item":"sage","raw":"1 tbsp sage, finely chopped","quantity":1,"unit":"tbsp","ingredientId":"sage","prep":"finely chopped"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"ground nutmeg","raw":"1/4 tsp ground nutmeg","quantity":0.25,"unit":"tsp","ingredientId":"nutmeg"}]},{"title":"Crumb","items":[{"item":"plain flour","raw":"50g plain flour","quantity":50,"unit":"g","ingredientId":"plain-flour"},{"item":"egg","raw":"1 egg, beaten","quantity":1,"ingredientId":"egg","prep":"beaten"},{"item":"panko breadcrumbs","raw":"100g panko breadcrumbs","quantity":100,"unit":"g","ingredientId":"panko"},{"item":"neutral oil","raw":"1.5L neutral oil, for deep-frying","quantity":1.5,"unit":"l","ingredientId":"neutral-oil","prep":"for deep-frying"}]},{"title":"To serve","items":[{"item":"English mustard","raw":"English mustard, to serve","ingredientId":"english-mustard","prep":"to serve"}]}],"steps":[{"text":"Lower the 6 eggs into a saucepan of boiling water and boil for 6 1/2 minutes. Move straight into iced water for 10 minutes, then peel carefully."},{"text":"Mix the sausage mince with the sage, pepper and nutmeg and divide into six. Flatten each portion into a thin patty on a piece of baking paper, sit an egg in the middle and wrap the meat around it, pinching to seal with no gaps."},{"text":"Roll each in flour, then the beaten egg, then the panko, pressing it on. Chill for 15 minutes."},{"text":"Heat the oven to 180°C (160°C fan-forced). Heat the oil in a deep, heavy saucepan to 160°C, no more than a third full. Fry the eggs two or three at a time for 6 to 7 minutes, turning, until deep golden. Drain on paper towel."},{"text":"Put them on a tray and bake for 8 to 10 minutes, until the sausage meat is cooked through (75°C when a thermometer is pushed into the meat). Rest for 5 minutes, then halve and serve warm or cold with mustard."}],"notes":["Runny yolks aren't recommended for pregnant people, young children, older people or anyone with a weakened immune system. Boil the eggs for 9 minutes for firm yolks.","Never leave hot oil unattended. Let it cool completely before you move or strain it.","Sausage mince is sold at the meat counter. Or squeeze good pork sausages out of their skins.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"kasespatzle","title":"Käsespätzle","cuisine":"central-european","meal_types":["dinner"],"diets":[],"difficulty":"medium","total_minutes":50,"recipe":{"id":"kasespatzle","title":"Käsespätzle","summary":"Soft homemade egg noodles layered with melting Gruyère and emmental under sweet fried onions.","cuisine":"central-european","diets":[],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":15,"cookMinutes":35,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Spätzle","items":[{"item":"plain flour","raw":"400g plain flour","quantity":400,"unit":"g","ingredientId":"plain-flour"},{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"milk","raw":"150ml milk","quantity":150,"unit":"ml","ingredientId":"milk"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"ground nutmeg","raw":"1/4 tsp ground nutmeg","quantity":0.25,"unit":"tsp","ingredientId":"nutmeg"}]},{"title":"Onions and cheese","items":[{"item":"butter","raw":"40g butter","quantity":40,"unit":"g","ingredientId":"butter"},{"item":"brown onions","raw":"3 brown onions, thinly sliced","quantity":3,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"Gruyère","raw":"200g Gruyère, grated","quantity":200,"unit":"g","ingredientId":"gruyere","prep":"grated"},{"item":"emmental","raw":"100g emmental, grated","quantity":100,"unit":"g","ingredientId":"swiss-cheese","prep":"grated"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"chives","raw":"2 tbsp chives, chopped","quantity":2,"unit":"tbsp","ingredientId":"chives","prep":"chopped"}]},{"title":"To serve","items":[{"item":"Green salad","raw":"Green salad, to serve","ingredientId":"salad-leaves","prep":"to serve"}]}],"steps":[{"text":"Beat the flour, eggs, milk, salt and nutmeg with a wooden spoon for 3 to 4 minutes, until the batter is thick, smooth and starts to bubble. Rest for 10 minutes."},{"text":"Meanwhile, melt the butter in a large frying pan over medium heat and cook the onions for 20 minutes, stirring often, until deep golden and soft. Heat the oven to 200°C (180°C fan-forced) and butter a baking dish."},{"text":"Bring a large saucepan of salted water to the boil. Press a third of the batter through a spätzle maker or a colander with large holes into the water. When the spätzle float, after about 1 minute, lift them out with a slotted spoon."},{"text":"Layer the hot spätzle in the dish with the cheeses and pepper, finishing with cheese. Repeat with the rest of the batter."},{"text":"Top with the onions and bake for 10 minutes, until the cheese has melted through. Scatter with chives and serve with a green salad."}],"notes":["If the batter won't drip through the holes, add a splash more milk. If it runs straight through, beat in a little more flour.","The cheeses are made with animal rennet, which some vegetarians avoid.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"kaiserschmarrn","title":"Kaiserschmarrn","cuisine":"central-european","meal_types":["breakfast"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"kaiserschmarrn","title":"Kaiserschmarrn","summary":"Austria's fluffy torn pancake with rum-soaked raisins, caramelised in the pan and dusted with icing sugar.","cuisine":"central-european","diets":["vegetarian"],"mealTypes":["breakfast"],"difficulty":"easy","prepMinutes":15,"cookMinutes":15,"servings":3,"onePot":true,"ingredientGroups":[{"title":"Pancake","items":[{"item":"raisins","raw":"50g raisins","quantity":50,"unit":"g","ingredientId":"raisins"},{"item":"rum","raw":"2 tbsp rum (optional)","quantity":2,"unit":"tbsp","ingredientId":"rum","optional":true},{"item":"eggs","raw":"4 eggs, separated","quantity":4,"ingredientId":"egg","prep":"separated"},{"item":"caster sugar","raw":"30g caster sugar","quantity":30,"unit":"g","ingredientId":"caster-sugar"},{"item":"vanilla extract","raw":"1 tsp vanilla extract","quantity":1,"unit":"tsp","ingredientId":"vanilla-extract"},{"item":"milk","raw":"250ml milk","quantity":250,"unit":"ml","ingredientId":"milk"},{"item":"plain flour","raw":"150g plain flour","quantity":150,"unit":"g","ingredientId":"plain-flour"},{"item":"salt","raw":"Pinch of salt","quantity":1,"unit":"pinch","ingredientId":"salt"},{"item":"butter","raw":"30g butter","quantity":30,"unit":"g","ingredientId":"butter"},{"item":"caster sugar","raw":"1 tbsp caster sugar, extra","quantity":1,"unit":"tbsp","ingredientId":"caster-sugar","prep":"extra"}]},{"title":"To serve","items":[{"item":"Icing sugar","raw":"Icing sugar, for dusting","ingredientId":"icing-sugar","prep":"for dusting"},{"item":"Apple sauce","raw":"Apple sauce, to serve","ingredientId":"apple-sauce","prep":"to serve"}]}],"steps":[{"text":"Soak the raisins in the rum (or warm water) for 10 minutes."},{"text":"Whisk the egg yolks, sugar and vanilla, then whisk in the milk and flour until smooth. In a clean bowl, whisk the egg whites with the salt to stiff peaks, then fold them gently into the batter."},{"text":"Melt half the butter in a large non-stick frying pan over medium-low heat. Pour in the batter and scatter over the drained raisins. Cook for 5 to 6 minutes, until the underside is golden and the top is starting to set."},{"text":"Cut the pancake into quarters and flip each one. Cook for 3 minutes more, then tear into bite-sized pieces with two forks."},{"text":"Add the rest of the butter and the extra sugar and toss for 2 minutes, until the edges caramelise and the pieces are cooked through. Dust with icing sugar and serve with apple sauce."}],"notes":["It's meant to look rough: the torn pieces catch the caramel.","Stewed plums are the traditional partner if you have them."],"source":"user","provenance":"ai-draft"}},{"slug":"lecso","title":"Lecsó","cuisine":"central-european","meal_types":["dinner","lunch"],"diets":["vegetarian","no-dairy"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"lecso","title":"Lecsó","summary":"Hungary's summer stew of yellow capsicum, tomato and onion with sweet paprika, with eggs stirred through.","cuisine":"central-european","diets":["vegetarian","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":35,"servings":4,"onePot":true,"seasons":["summer","autumn"],"ingredientGroups":[{"items":[{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"kransky","raw":"200g kransky, sliced (optional)","quantity":200,"unit":"g","ingredientId":"smoked-sausage","prep":"sliced","optional":true},{"item":"brown onions","raw":"2 brown onions, thinly sliced","quantity":2,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"yellow capsicums","raw":"3 yellow capsicums, cut into 1cm strips","quantity":3,"ingredientId":"capsicum","prep":"cut into 1cm strips"},{"item":"red capsicum","raw":"1 red capsicum, cut into 1cm strips","quantity":1,"ingredientId":"capsicum","prep":"cut into 1cm strips"},{"item":"sweet paprika","raw":"2 tsp sweet paprika","quantity":2,"unit":"tsp","ingredientId":"paprika"},{"item":"tomatoes","raw":"4 tomatoes, chopped","quantity":4,"ingredientId":"tomato","prep":"chopped"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"sugar","raw":"1/2 tsp sugar","quantity":0.5,"unit":"tsp","ingredientId":"sugar"},{"item":"eggs","raw":"4 eggs, lightly beaten","quantity":4,"ingredientId":"egg","prep":"lightly beaten"},{"item":"Crusty bread","raw":"Crusty bread, to serve","ingredientId":"crusty-bread","prep":"to serve"}]}],"steps":[{"text":"Heat the oil in a large frying pan or wide saucepan over medium heat. If using the kransky, fry it for 3 minutes until browned and lift it out."},{"text":"Cook the onions for 8 minutes until soft and golden. Add the capsicums and cook for 10 minutes, stirring now and then, until softened."},{"text":"Take the pan off the heat and stir in the paprika (it burns easily), then return to the heat and add the tomatoes, salt and sugar. Simmer for 10 to 12 minutes, until the tomatoes have collapsed into a thick sauce. Return the kransky, if using."},{"text":"Pour in the eggs and stir gently over low heat for 2 to 3 minutes, until just set in soft curds."},{"text":"Serve straight away with crusty bread."}],"notes":["Long, pale Hungarian wax peppers are traditional. Look for them at greengrocers in late summer.","Without the eggs, lecsó is also a great sauce for sausages or rice.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;